import { WindowConf, createDefaultWindowConf } from "@droid/android";
import { ulid } from "ulid";
import { createActionUtils, IActionData, IActionJavaData, IActionShellData } from "@droid/project-interface";
import { floatWindowNamespace } from "../float-window-namespace";
import { IActionShowFloatWindowUI } from "./IActionShowFloatWindow.UI";

const type = `${floatWindowNamespace}showFloatWindow`

export interface IActionShowFloatWindowJavaData extends IActionJavaData {
    windowConf: WindowConf
}

export interface IActionShowFloatWindowData extends IActionData<IActionShellData, IActionShowFloatWindowJavaData> {
    javaData: IActionShowFloatWindowJavaData
}

function createDefaultData(): IActionShowFloatWindowData {
    console.log('[IActionShowFloatWindow] createDefaultData called')
    const data: IActionShowFloatWindowData = {
        id: ulid(),
        type,
        javaData: {
            windowConf: createDefaultWindowConf()
        }
    }
    console.log('[IActionShowFloatWindow] createDefaultData result:', data)
    return data
}

function init() {
    console.log('[IActionShowFloatWindow] init called')
}

export const actionShowFloatWindowUtils = createActionUtils(type, init, createDefaultData, IActionShowFloatWindowUI)
